/bin/bash -lc "python - <<'PY'
import cv2,numpy as np
F=np.load('source_pixels.npz')['rgb']
for typ in ['y','p']:
 print('\\n',typ)
 for t in range(96):
  a=F[t].astype(int)
  if typ=='y': m=(a[:,:,0]>145)&(a[:,:,1]>95)&(a[:,:,0]-a[:,:,2]>60)&(a[:,:,1]-a[:,:,2]>30)
  else: m=(a[:,:,2]>125)&(a[:,:,2]-a[:,:,0]>25)&(a[:,:,2]-a[:,:,1]>45)
  # only scene region
  m[:45]=0;m[92:]=0
  n,l,st,c=cv2.connectedComponentsWithStats(m.astype('uint8'),8)
  cand=[]
  for s,cc in zip(st[1:],c[1:]):
   x,y,w,h,ar=s
   if ar>=5: cand.append((ar,cc[0],cc[1],x,y,w,h))
  if cand:
   z=max(cand)
   print(f'{t:02d}: {z[1]:6.2f},{z[2]:5.2f} a{z[0]:3d} box{z[3:]}')
PY"
